"""Small shared structures for the command line HTTP client."""
import os
import sys
import re
import json

VERSION = '0.25.3'
BINARY_NOTICE = (b'+-----------------------------------------+\n'
                 b'| NOTE: binary data not shown in terminal |\n'
                 b'+-----------------------------------------+\n')

class Failure(Exception):
    def __init__(self, text, code=1, cli=False):
        super().__init__(text)
        self.text = text
        self.code = code
        self.cli = cli


def fail(text, code=1):
    raise Failure(text, code)


def io_error(exc):
    if isinstance(exc, UnicodeError):
        return 'stream did not contain valid UTF-8'
    if isinstance(exc, OSError):
        return f'{exc.strerror} (os error {exc.errno})'
    return str(exc)


def read_bytes(path):
    try:
        with open(os.path.expanduser(path), 'rb') as f:
            return f.read()
    except OSError as e:
        fail(io_error(e))


def read_text(path):
    try:
        return read_bytes(path).decode('utf-8')
    except UnicodeError as e:
        fail(io_error(e))


def rust_debug(text):
    s = json.dumps(text, ensure_ascii=False)
    s = s.replace('\\u0000', '\\0')
    return s


class Headers:
    """Ordered case-insensitive multimap, including swap removal semantics."""
    def __init__(self, entries=None):
        self.data = []
        if entries:
            for key, value in entries:
                self.append(key, value)

    def index(self, name):
        name = name.lower()
        for i, (k, _) in enumerate(self.data):
            if k == name:
                return i
        return -1

    def __contains__(self, name):
        return self.index(name) >= 0

    def get(self, name, default=None):
        i = self.index(name)
        return self.data[i][1][0] if i >= 0 else default

    def getall(self, name):
        i = self.index(name)
        return self.data[i][1][:] if i >= 0 else []

    def set(self, name, value):
        values = value[:] if isinstance(value, list) else [value]
        name = name.lower()
        i = self.index(name)
        if i < 0:
            self.data.append((name, values))
        else:
            self.data[i] = (name, values)

    def append(self, name, value):
        i = self.index(name)
        if i >= 0:
            self.data[i][1].append(value)
        else:
            self.data.append((name.lower(), [value]))

    def remove(self, name):
        i = self.index(name)
        if i >= 0:
            result = self.data[i][1]
            self.data[i] = self.data[-1]
            self.data.pop()
            return result
        return []

    def extend(self, other):
        for name, values in other.data:
            self.set(name, values)

    def items(self, sort=False):
        data = sorted(self.data) if sort else self.data
        for key, values in data:
            for value in values:
                yield key, value

    def copy(self):
        return Headers(self.items())


def valid_header_name(name):
    return bool(re.fullmatch(r"[!#$%&'*+.^_`|~0-9A-Za-z-]+", name))


def header_value(value):
    if isinstance(value, str):
        value = value.encode('utf-8')
    if any((c < 32 and c != 9) or c == 127 for c in value):
        fail('failed to parse header value')
    return value


def display_header_value(value):
    if isinstance(value, str):
        value = value.encode('utf-8')
    result = value.decode('latin-1')
    if any(c >= 128 for c in value):
        try:
            decoded = value.decode('utf-8')
            result += ' (UTF-8: ' + decoded + ')'
        except UnicodeError:
            pass
    return result


def warning(text, options=None):
    if options is not None and options.get('quiet', 0) >= 2:
        return
    name = options.bin_name if options is not None else os.path.basename(sys.argv[0])
    sys.stderr.write(f'{name}: warning: {text}\n')
PY"}

