{"command":"cat > src/jsoncodec.py <<'PY'
"""JSON parsing and serialization with stable ordering and precise diagnostics."""
import json
import math
import re

class JsonError(ValueError):
    pass

class Pairs:
    def __init__(self, pairs):
        self.pairs = pairs

class Parser:
    def __init__(self, text, pairs=False):
        self.s = text
        self.i = 0
        self.keep_pairs = pairs
        self.depth = 0

    def err(self, message, at=None):
        at = self.i if at is None else at
        at = max(0, min(at, len(self.s)))
        prefix = self.s[:at]
        line = prefix.count('\n') + 1
        column = len(prefix.rsplit('\n', 1)[-1].encode('utf-8'))
        raise JsonError(f'{message} at line {line} column {column}')

    def ws(self):
        while self.i < len(self.s) and self.s[self.i] in ' \t\r\n':
            self.i += 1

    def parse(self):
        value = self.value()
        self.ws()
        if self.i != len(self.s):
            self.err('trailing characters', self.i + 1)
        return value

    def value(self):
        self.ws()
        if self.i >= len(self.s):
            self.err('EOF while parsing a value')
        ch = self.s[self.i]
        if ch == '"':
            return self.string()
        if ch in '-0123456789':
            return self.number()
        if ch in 'ntf':
            word, val = {'n': ('null', None), 't': ('true', True), 'f': ('false', False)}[ch]
            for c in word:
                if self.i >= len(self.s):
                    self.err('EOF while parsing a value')
                if self.s[self.i] != c:
                    self.err('expected ident', self.i + 1)
                self.i += 1
            return val
        if ch in '[{':
            self.depth += 1
            if self.depth >= 128:
                self.err('recursion limit exceeded', self.i + 1)
            value = self.array() if ch == '[' else self.object()
            self.depth -= 1
            return value
        self.err('expected value', self.i + 1)

    def number(self):
        start = self.i
        if self.s[self.i] == '-':
            self.i += 1
        if self.i >= len(self.s):
            self.err('EOF while parsing a value')
        if self.s[self.i] == '0':
            self.i += 1
            if self.i < len(self.s) and self.s[self.i].isdigit():
                self.err('invalid number', self.i + 1)
        elif self.s[self.i] in '123456789':
            while self.i < len(self.s) and self.s[self.i] in '0123456789':
                self.i += 1
        else:
            self.err('invalid number', self.i + 1)
        real = False
        if self.i < len(self.s) and self.s[self.i] == '.':
            real = True
            self.i += 1
            if self.i >= len(self.s):
                self.err('EOF while parsing a value')
            if self.s[self.i] not in '0123456789':
                self.err('invalid number', self.i + 1)
            while self.i < len(self.s) and self.s[self.i] in '0123456789':
                self.i += 1
        if self.i < len(self.s) and self.s[self.i] in 'eE':
            real = True
            self.i += 1
            if self.i < len(self.s) and self.s[self.i] in '+-':
                self.i += 1
            if self.i >= len(self.s):
                self.err('EOF while parsing a value')
            if self.s[self.i] not in '0123456789':
                self.err('invalid number', self.i + 1)
            while self.i < len(self.s) and self.s[self.i] in '0123456789':
                self.i += 1
        token = self.s[start:self.i]
        if not real and token != '-0':
            val = int(token)
            if -(1 << 63) <= val < (1 << 64):
                return val
        val = float(token)
        if not math.isfinite(val):
            self.err('number out of range', self.i)
        return val

    def string(self):
        self.i += 1
        out = []
        while self.i < len(self.s):
            ch = self.s[self.i]
            self.i += 1
            if ch == '"':
                return ''.join(out)
            if ord(ch) < 32:
                self.err('control character (\\u0000-\\u001F) found while parsing a string')
            if ch != '\\':
                out.append(ch)
                continue
            if self.i >= len(self.s):
                self.err('EOF while parsing a string')
            ch = self.s[self.i]
            self.i += 1
            escapes = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
            if ch in escapes:
                out.append(escapes[ch])
            elif ch == 'u':
                code = self.hex4()
                if 0xD800 <= code <= 0xDBFF:
                    if not self.s.startswith('\\u', self.i):
                        self.err('unexpected end of hex escape', min(len(self.s), self.i + 1))
                    self.i += 2
                    low = self.hex4()
                    if not 0xDC00 <= low <= 0xDFFF:
                        self.err('lone leading surrogate in hex escape')
                    code = 0x10000 + ((code - 0xD800) << 10) + low - 0xDC00
                elif 0xDC00 <= code <= 0xDFFF:
                    self.err('lone leading surrogate in hex escape')
                out.append(chr(code))
            else:
                self.err('invalid escape')
        self.err('EOF while parsing a string')

    def hex4(self):
        chars = ''
        for _ in range(4):
            if self.i >= len(self.s):
                self.err('EOF while parsing a string')
            ch = self.s[self.i]
            self.i += 1
            if ch not in '0123456789abcdefABCDEF':
                self.err('invalid escape')
            chars += ch
        return int(chars, 16)

    def array(self):
        self.i += 1
        self.ws()
        result = []
        if self.i < len(self.s) and self.s[self.i] == ']':
            self.i += 1
            return result
        while True:
            if self.i >= len(self.s):
                self.err('EOF while parsing a list')
            result.append(self.value())
            self.ws()
            if self.i >= len(self.s):
                self.err('EOF while parsing a list')
            ch = self.s[self.i]
            self.i += 1
            if ch == ']':
                return result
            if ch != ',':
                self.err("expected `,` or `]`")
            self.ws()
            if self.i < len(self.s) and self.s[self.i] == ']':
                self.err('trailing comma', self.i + 1)

    def object(self):
        self.i += 1
        self.ws()
        pairs = []
        if self.i < len(self.s) and self.s[self.i] == '}':
            self.i += 1
            return Pairs(pairs) if self.keep_pairs else {}
        while True:
            if self.i >= len(self.s):
                self.err('EOF while parsing an object')
            if self.s[self.i] != '"':
                self.err('key must be a string', self.i + 1)
            key = self.string()
            self.ws()
            if self.i >= len(self.s):
                self.err('EOF while parsing an object')
            if self.s[self.i] != ':':
                self.err('expected `:`', self.i + 1)
            self.i += 1
            pairs.append((key, self.value()))
            self.ws()
            if self.i >= len(self.s):
                self.err('EOF while parsing an object')
            ch = self.s[self.i]
            self.i += 1
            if ch == '}':
                return Pairs(pairs) if self.keep_pairs else dict(pairs)
            if ch != ',':
                self.err("expected `,` or `}`")
            self.ws()
            if self.i < len(self.s) and self.s[self.i] == '}':
                self.err('trailing comma', self.i + 1)


def loads(text, pairs=False):
    return Parser(text, pairs).parse()


def floatstr(value):
    s = repr(value)
    if 'e' not in s:
        return s
    sig, exp = s.split('e')
    exp = int(exp)
    if -5 <= exp < 16:
        # Ryu uses decimal notation for small but ordinary fractions.
        negative = sig.startswith('-')
        sig = sig.lstrip('-')
        digits = sig.replace('.', '')
        point = sig.find('.')
        if point < 0:
            point = len(sig)
        point += exp
        if point <= 0:
            result = '0.' + '0' * (-point) + digits
        elif point >= len(digits):
            result = digits + '0' * (point - len(digits)) + '.0'
        else:
            result = digits[:point] + '.' + digits[point:]
        return ('-' if negative else '') + result
    if sig.endswith('.0'):
        sig = sig[:-2]
    return sig + 'e' + str(exp)


def dumps(value, indent=None, level=0):
    if value is None:
        return 'null'
    if value is True:
        return 'true'
    if value is False:
