    beforefrag = text.split('#', 1)[0]
    query = parts.query if '?' in beforefrag else None
    fragment = parts.fragment if '#' in text else None
    if query is not None:
        query = urllib.parse.quote(query, safe='!$&()*+,-./:;=?@_~%[]|\\^`{}' + ('' if special else "'"))
    if fragment is not None:
        fragment = urllib.parse.quote(fragment, safe="!#$&'()*+,-./:;=?@_~%[]|\\^{}")
