                        text = f"error: a value is required for '--{base} <{VALUE_OPTIONS[base]}>' but none was supplied\n"
                        if base in ENUMS:
                            text += '  [possible values: ' + ', '.join(ENUMS[base]) + ']\n'
                        raise Failure(text + FOOTER, 2, True)
                val = validate_value(opts, base, val)
            else:
                if val is not None:
                    usage = opts.usage(active=[key])
                    raise Failure(f"error: unexpected value '{val}' for '--{key}' found; no more were expected\n\n" + usage + '\n' + FOOTER, 2, True)
                val = True
            opts.set(key, val)
    for key, other in [('multipart','raw'), ('session','session-read-only')]:
        if opts[key] and opts[other] is not None and opts[other] is not False:
            a = '--'+key + (' <'+VALUE_OPTIONS[key]+'>' if key in VALUE_OPTIONS else '')
            b = '--'+other+' <'+VALUE_OPTIONS[other]+'>'
            text = f"error: the argument '{a}' cannot be used with '{b}'\n\n"
            active = [k for k in opts.active if k != other and not k.startswith('no-')]
