        return opts
    if opts['generate']:
        return opts
    missing = []
    if opts['continue']:
        if not opts['download']: missing.append('--download')
        if opts['output'] is None: missing.append('--output <FILE>')
    if not opts.positionals:
        missing.append('<[METHOD] URL>')
    if missing:
        text = 'error: the following required arguments were not provided:\n' + ''.join('  ' + x + '\n' for x in missing)
        active = [m.split()[0][2:] for m in missing if m.startswith('--')] + [k for k in opts.active if not k.startswith('no-')]
        raise Failure(text + '\n' + opts.usage(active=active) + '\n' + FOOTER, 2, True)
    rest = opts.positionals[:]
    if re.fullmatch('[A-Za-z]+', rest[0]):
        opts.method = rest.pop(0).upper()
        if not rest:
            opts.error('Missing <URL>')
    urltext = rest.pop(0)
    default_scheme = opts['default-scheme'] or ('https' if opts.bin_name in ('https','xhs','xhttps') else 'http')
    if opts['https']:
        default_scheme = 'https'
    try:
        opts.url = parse_url(urltext, default_scheme)
    except UrlError as e:
        opts.error('Invalid <URL>: ' + str(e))
    from request import parse_items
    opts.items = parse_items(opts, rest)
    if opts['raw'] is not None and any(item.kind in ('data','json','file') for item in opts.items):
        opts.error('Request body (from --raw) and request data (key=value) cannot be mixed.', name='xh')
    for d in opts['format-options']:
        opts.format_values.update(d)
    return opts
