        if usage:
            out += '\n' + self.usage(generic, name=name) + '\n'
        raise Failure(out + FOOTER, 2, True)

    def invalid(self, key, value, reason=None):
        text = f"error: invalid value '{value}' for '--{key} <{VALUE_OPTIONS[key]}>'"
        if reason:
