ESCAPES = ':;=@\\'


def unescape(text, brackets=False):
    special = ESCAPES + ('[]' if brackets else '')
    out = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == '\\' and i + 1 < len(text) and text[i+1] in special:
            i += 1
            ch = text[i]
        out.append(ch)
        i += 1
    return ''.join(out)


