"""Request item syntax, nested JSON paths, and body encoders."""
import os
import sys
import re
import mimetypes
import secrets
from dataclasses import dataclass
from common import Failure, fail, read_bytes, read_text, valid_header_name, header_value, Headers, rust_debug, warning
from urlutil import form_encode
import jsoncodec

ESCAPES = ':;=@\\'


def unescape(text, brackets=False):
    special = ESCAPES + ('[]' if brackets else '')
    out = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == '\\' and i + 1 < len(text) and text[i+1] in special:
            i += 1
            ch = text[i]
        out.append(ch)
        i += 1
    return ''.join(out)


@dataclass
class Item:
    kind: str
    key: str
    value: object
    fromfile: bool = False
    raw: str = ''
    mime: object = None
    filename: object = None


def split_file_tags(value):
    # Tag values may contain semicolons, except for another recognized tag.
    matches = list(re.finditer(r';(type|filename)=', value))
    path = value[:matches[0].start()] if matches else value
    mime = filename = None
    for i, m in enumerate(matches):
        val = value[m.end():matches[i+1].start() if i+1 < len(matches) else len(value)]
        if m[1] == 'type': mime = val
        else: filename = val
    return path, mime, filename


def parse_items(opts, args):
    items = []
    for raw in args:
        i = 0
        sep = None
        while i < len(raw):
            if raw[i] == '\\' and i+1 < len(raw) and raw[i+1] in ESCAPES:
                i += 2
                continue
            if raw[i] in ':=@;':
                sep = raw[i]
                if raw[i:i+2] in (':=', '=='):
                    sep = raw[i:i+2]
                break
            i += 1
        if sep is None or (sep == ';' and i != len(raw)-1):
            opts.error("Invalid value for '[REQUEST_ITEM]...': " + rust_debug(raw))
        key = unescape(raw[:i])
        value = raw[i+len(sep):]
        fromfile = value.startswith('@') and sep in (':', '=', ':=', '==')
        if fromfile:
            value = value[1:]
        value = unescape(value)
        kind = {':': 'header', ';': 'empty-header', '=': 'data', ':=': 'json', '==': 'query', '@': 'file'}[sep]
        if sep == ':' and value == '' and not fromfile:
            kind = 'unset'
        item = Item(kind, key, value, fromfile, raw)
        if kind == 'json' and not fromfile:
            try:
                item.value = jsoncodec.loads(value)
            except jsoncodec.JsonError as e:
                opts.error("Invalid value for '[REQUEST_ITEM]...': " + rust_debug(raw) + ' ' + str(e))
        if kind == 'file':
            item.value, item.mime, item.filename = split_file_tags(value)
        items.append(item)
    return items


def path_error(key, message, at, length=1):
    shown = key + (' ' if at >= len(key) else '')
    fail(message + '\n\n  ' + shown + '\n  ' + ' ' * at + '^' * max(1, length))


def parse_path(key):
    parts = []
    i = 0
    def text_until():
        nonlocal i
        text = []
        while i < len(key):
            if key[i] == '\\' and i+1 < len(key) and key[i+1] in '[]\\':
                text.append(key[i+1])
                i += 2
                continue
            if key[i] in '[]': break
            text.append(key[i])
            i += 1
        return ''.join(text)
    text = text_until()
    if text:
        parts.append(('key', text, 0, i))
    if not parts and (i >= len(key) or key[i] != '['):
        path_error(key, "expected text or '['", i)
    while i < len(key):
        if key[i] != '[':
            path_error(key, "expected '['", i)
        start = i
        i += 1
        text = text_until()
        if i >= len(key):
            path_error(key, "expected ']'", i)
        if key[i] == '[':
            path_error(key, "expected text, number or ']'", i)
        i += 1
        if not text:
            kind, value = 'append', None
        elif re.fullmatch('[0-9]+', text) and int(text) < (1 << 64):
            kind, value = 'index', int(text)
        else:
            kind, value = 'key', text
        parts.append((kind, value, start, i-start))
    return parts


def typename(value):
    if value is None: return 'null'
    if isinstance(value, bool): return 'boolean'
    if isinstance(value, (int, float)): return 'number'
    if isinstance(value, str): return 'string'
    if isinstance(value, dict): return 'object'
    return 'array'


MISSING = object()


def add_json(root, key, value):
    parts = parse_path(key)
    def assign(node, depth):
        kind, name, start, length = parts[depth]
        obj = kind == 'key'
        if node is MISSING:
            node = {} if obj else []
        expected = dict if obj else list
        if not isinstance(node, expected):
            msg = (f"Can't perform '{kind}' based access on '{key[:start]}' which has a type of "
                   f"'{typename(node)}' but this operation requires a type of '{'object' if obj else 'array'}'.")
            path_error(key, msg, start, length)
        final = depth == len(parts) - 1
        if obj:
            node[name] = value if final else assign(node.get(name, MISSING), depth + 1)
        else:
            index = len(node) if kind == 'append' else name
            if index > 1000000:
                fail('JSON array index is too large')
            was_missing = index >= len(node)
            if was_missing:
                node.extend([None] * (index + 1 - len(node)))
            node[index] = value if final else assign(MISSING if was_missing else node[index], depth + 1)
        return node
    return assign(root, 0)


def guess_mime(path):
    extension = os.path.splitext(path)[1].lower()
    common = {'.json': 'application/json', '.txt': 'text/plain', '.html': 'text/html', '.htm': 'text/html',
              '.css': 'text/css', '.js': 'text/javascript', '.csv': 'text/csv', '.xml': 'text/xml',
              '.md': 'text/markdown', '.svg': 'image/svg+xml', '.pdf': 'application/pdf',
              '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.gif': 'image/gif',
              '.wasm': 'application/wasm', '.yaml': 'text/x-yaml', '.yml': 'text/x-yaml'}
    return common.get(extension) or mimetypes.guess_type(path)[0] or 'application/octet-stream'


@dataclass
class Body:
    data: object = None
    kind: str = 'none'
    mime: object = None
    json_defaults: bool = False
    method_body: bool = False
    stream: bool = False
    path: object = None
    fields: object = None


@dataclass
class Components:
    body: Body
    headers: Headers
    unsets: list
    fields: list


def components(opts, curl=False):
    headers = Headers()
    unsets = []
    query = []
    fields = []
    for original in opts.items:
        item = Item(**vars(original))
        if item.fromfile:
            value = read_text(item.value)
            if item.kind == 'json':
                try:
                    value = jsoncodec.loads(value)
                except jsoncodec.JsonError as e:
                    fail(str(e))
            elif item.kind == 'header':
                value = value.strip()
            item.value = value
        if item.kind in ('header', 'empty-header', 'unset'):
            key = unescape(item.key, True).lower()
            if not valid_header_name(key):
                fail('invalid HTTP header name')
            if item.kind == 'unset':
                headers.remove(key)
                if key not in unsets: unsets.append(key)
            else:
                value = b'' if item.kind == 'empty-header' else header_value(item.value)
                headers.append(key, value)
                if key in unsets: unsets.remove(key)
        elif item.kind == 'query':
            query.append((unescape(item.key, True), item.value))
        else:
            fields.append(item)
    opts.url.add_query(query)
    form = opts['form'] or opts['multipart']
    files = [f for f in fields if f.kind == 'file']
    if form and any(f.kind == 'json' for f in fields):
        fail('JSON values are not supported in Form fields')
    if not form and files:
        if any(f.key for f in files):
            fail("Can't use file fields in JSON mode (perhaps you meant --form?)")
        if len(files) > 1:
            fail("Can't read request from multiple files")
        if len(fields) > 1:
            fail('Request body (from a file) and request data (key=value) cannot be mixed.')
    stdin_present = not curl and not opts['ignore-stdin'] and not sys.stdin.isatty()
    if stdin_present:
        if fields:
            fail('Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.')
        if opts['raw'] is not None:
            fail('Request body from stdin and --raw cannot be mixed. Pass --ignore-stdin to ignore standard input.')
        if opts['multipart']:
            fail('Cannot build a multipart request body from stdin')
        try:
            data = sys.stdin.buffer.read()
        except OSError as e:
            from common import io_error
            fail(io_error(e))
        body = Body(data, 'raw', 'application/x-www-form-urlencoded' if form else 'application/json', not form, True)
    elif opts['raw'] is not None:
        body = Body(opts['raw'].encode(), 'raw', 'application/x-www-form-urlencoded' if form else 'application/json', not form, True)
    elif form and (files or opts['multipart']):
        if curl:
            body = Body(None, 'multipart', None, False, True, True, fields=fields)
        else:
