                        header += '\r\nContent-Type: ' + item.mime
                    data = read_bytes(path)
                else:
                    data = item.value.encode('utf-8')
                chunks.extend([header.encode() + b'\r\n\r\n', data, b'\r\n'])
            if fields:
                chunks.append(('--' + boundary + '--\r\n').encode())
            body = Body(b''.join(chunks), 'multipart', 'multipart/form-data; boundary=' + boundary, False, True, True, fields=fields)
    elif files:
