    elif form:
        pairs = [(unescape(f.key, True), f.value) for f in fields]
        body = Body(form_encode(pairs).encode(), 'form', 'application/x-www-form-urlencoded', False, bool(fields), fields=fields)
    elif fields:
        root = MISSING
        for item in fields:
            root = add_json(root, item.key, item.value)
        body = Body(jsoncodec.dumps(root).encode('utf-8'), 'json', 'application/json', True, True, fields=fields)
    elif opts['json']:
        body = Body(None, 'none', 'application/json', True, False)
    else:
        body = Body()
    return Components(body, headers, unsets, fields)
