def credentials(opts, session=None):
    if opts['bearer'] is not None:
        return 'bearer', opts['bearer']
    if opts['auth'] is not None:
        return opts['auth-type'] or 'basic', opts['auth']
    if session and session.auth.get('raw_auth') is not None:
