"""Human-readable request and response presentation."""
import os
import sys
import re
from common import BINARY_NOTICE, display_header_value, fail, io_error
import jsoncodec
from cli import encoding_name

RESET = '\x1b[0m'

# Palette indices and token categories for the four built-in styles.
PALETTES = {
    'auto': {'plain':'','method':'32','url':'4m\x1b[36','proto':'34','slash':'','version':'34',
             'header':'36','colon':'','value':'','key':'38;5;12','string':'33','number':'34','literal':'34',
             'status':'32','reason':''},
    'monokai': {'plain':'38;5;15','method':'38;5;148','url':'38;5;15','proto':'38;5;81','slash':'38;5;197','version':'38;5;141',
                'header':'38;5;148','colon':'38;5;197','value':'38;5;186','key':'38;5;197','string':'38;5;186',
                'number':'38;5;141','literal':'38;5;81','status':'38;5;141','reason':'38;5;15'},
    'solarized': {'plain':'38;5;245','method':'38;5;33','url':'38;5;245','proto':'38;5;33','slash':'38;5;245','version':'38;5;37',
                  'header':'38;5;245','colon':'38;5;245','value':'38;5;37','key':'38;5;33','string':'38;5;37',
                  'number':'38;5;37','literal':'38;5;166','status':'38;5;37','reason':'38;5;245'},
    'fruity': {'plain':'38;5;15','method':'1m\x1b[38;5;198','url':'38;5;15','proto':'38;5;198','slash':'38;5;15','version':'38;5;33',
               'header':'38;5;198','colon':'38;5;15','value':'38;5;32','key':'38;5;202','string':'38;5;32',
               'number':'38;5;33','literal':'38;5;202','status':'38;5;33','reason':'38;5;15'},
}


class Printer:
    def __init__(self, opts):
        self.opts = opts
        self.download = opts['download']
        self.file = None
        self.tty = sys.stdout.isatty() and opts['output'] is None
        if self.download:
            self.dest = sys.stderr.buffer
            tty = sys.stderr.isatty()
            self.pretty = opts['pretty'] or ('all' if tty and not os.environ.get('NO_COLOR') else 'format')
            self.tty = tty
        else:
            if opts['output'] is not None:
                try:
                    self.file = open(os.path.expanduser(opts['output']), 'wb')
                except OSError as e:
                    fail(io_error(e))
            self.dest = self.file or sys.stdout.buffer
            tty = self.tty
            self.pretty = opts['pretty'] or ('all' if tty and not os.environ.get('NO_COLOR') else 'format' if tty else 'none')
        self.color = self.pretty in ('all', 'colors')
        self.format = self.pretty in ('all', 'format')
        self.sort = self.format and opts.format_values['headers.sort']
        self.json_format = self.format and opts.format_values['json.format']
        self.indent = opts.format_values['json.indent']
        self.palette = PALETTES[opts['style'] or 'auto']
        self.print_spec = self.select_print()

    def select_print(self):
        o = self.opts
        if o['print'] is not None:
            return o['print']
        if o['verbose']:
            return 'HBhbm' if o['verbose'] > 1 else 'HBhb'
        if o['quiet']:
            return ''
        if o['offline']:
            return 'HB'
        if o['headers'] or o['body'] or o['meta']:
            return ('h' if o['headers'] else '') + ('b' if o['body'] else '') + ('m' if o['meta'] else '')
        if self.download:
            return 'h'
        return 'hb' if self.tty else 'b'

    def write(self, value):
        if isinstance(value, str): value = value.encode('utf-8')
        try:
            self.dest.write(value)
            self.dest.flush()
        except BrokenPipeError:
            raise
        except OSError as e:
            fail(io_error(e))

    def token(self, kind, text):
        code = self.palette.get(kind, self.palette['plain'])
        return RESET + ('\x1b[' + code + 'm' if code else '') + text

    def header_block(self, first, headers, version='1.1', response=False):
        lines = list(headers.items(self.sort))
        if not self.color:
            data = first + '\n'
            for key,value in lines:
                name = key if version.startswith(('2', '3')) else '-'.join(part[:1].upper() + part[1:] for part in key.split('-'))
                data += name + ': ' + display_header_value(value) + '\n'
            return (data + '\n').encode()
        t = self.token
        if response:
            m = re.match(r'HTTP/([^ ]+) ([0-9]+)(.*)', first)
            if m:
                data = t('proto','HTTP')+t('slash','/')+t('version',m[1])+t('plain',' ')+t('status',m[2])+t('plain',m[3]+'\n')
            else:
                data = t('plain', first + '\n')
        else:
            method, url, proto = first.split(' ',2)
            data = t('method', method) + t('plain',' ') + t('url',url) + t('plain',' ') + t('proto','HTTP') + t('slash','/') + t('version',proto[5:]) + t('plain','\n')
        for key,value in lines:
            name = key if version.startswith(('2', '3')) else '-'.join(part[:1].upper()+part[1:] for part in key.split('-'))
            data += t('header',name)+t('colon',':')+t('plain',' ')+t('value',display_header_value(value))+t('plain','\n')
        return (data + RESET + '\n').encode()

    def highlight_json(self, text):
        out = []
        token = re.compile(r'"(?:[^"\\]|\\.)*"|\b(?:true|false|null)\b|-?(?:\d[\d,]*(?:\.\d*)?(?:[Ee][+-]?\d+)?)')
        for line in text.splitlines(keepends=True):
            end = 0
            for m in token.finditer(line):
                if m.start() > end:
                    out.append(self.token('plain', line[end:m.start()]))
                raw = m[0]
                if raw.startswith('"'):
                    iskey = bool(re.match(r'\s*:', line[m.end():]))
                    if iskey:
                        out.extend([self.token('key','"'), self.token('key', raw[1:-1]) if raw[1:-1] else '', self.token('key','"')])
                    else:
                        out.append(self.token('string', raw))
                elif raw[0] in 'tfn':
                    out.append(self.token('literal',raw))
                else:
                    out.append(self.token('number',raw))
                end = m.end()
            if end < len(line):
                out.append(self.token('plain', line[end:]))
        out.append(RESET)
        return ''.join(out)

    def body(self, data, mime=None, request=False):
        if data is None:
