    try:
        import termios
        tty = os.open('/dev/tty', os.O_RDWR)
        attrs = termios.tcgetattr(tty)
        new = attrs[:]
        new[3] &= ~termios.ECHO
        termios.tcsetattr(tty, termios.TCSANOW, new)
        try:
            os.write(tty, (f'http: password for {user}@{host}: ').encode())
            password = b''
            while True:
                c = os.read(tty, 1)
                if not c or c in (b'\n', b'\r'): break
                password += c
            os.write(tty,b'\n')
        finally:
            termios.tcsetattr(tty, termios.TCSANOW, attrs)
            os.close(tty)
        return password.decode('utf-8')
    except OSError as e:
        fail(io_error(e))


