    kind, raw = auth
    if kind == 'bearer':
        return header_value('Bearer ' + raw)
    if kind == 'digest':
        return None
    user, sep, password = raw.partition(':')
    if not sep:
        password = prompt_password(user, opts.url.host)
    return b'Basic ' + base64.b64encode((user + ':' + password).encode())


